// config.js: what the shared map-quiz engine (main.js, contract.js) needs
// to know about Wiener Bezirke: the data (districts.js, generated by
// tools/build_map.py) and every text the engine shows, in German. Static
// text (title, help, button labels before the script runs) is in
// index.html. Contract: shared/map-quiz/README.md.
import { MAP, DISTRICTS } from './districts.js';

const fehler = (n) => (n ? ` · ${n} Fehlklick${n === 1 ? '' : 's'}` : ' · ohne Fehlklick');
const label = (d) => `${d.name} · ${d.number}.`; // a misclick: "Leopoldstadt · 2."

export default {
  map: MAP,
  items: DISTRICTS,
  rounds: [
    {
      key: 'names',
      label: 'Namen',
      prompt: 'Finde',
      ask: (d) => d.name,
      miss: label,
      done: ({ total, misses }) => `Alle ${total} Bezirke gefunden${fehler(misses)}. Jetzt die Nummern.`,
    },
    {
      key: 'numbers',
      label: 'Nummern',
      prompt: 'Finde den',
      ask: (d) => `${d.number}. Bezirk`,
      miss: label,
      done: ({ total, misses }) => `Alle ${total} Nummern gefunden${fehler(misses)}. Wieder die Namen, neu gemischt.`,
    },
  ],
  text: {
    intro: {
      mouse: 'Klicke auf den gesuchten Bezirk. Zoomen mit dem Mausrad oder zwei Fingern, verschieben durch Ziehen.',
      touch: 'Tippe auf den gesuchten Bezirk. Zoomen mit zwei Fingern, verschieben durch Ziehen.',
    },
    newGame: 'Neues Spiel: Zähler auf null, zuerst die Namen.',
    reset: 'Quiz zurücksetzen',
    resetArmed: 'Wirklich zurücksetzen? Zähler und Farben werden gelöscht',
    mapError: 'Das Quiz konnte nicht geladen werden. Bitte lade die Seite neu.',
    theme: (other, override) => {
      const to = `In den ${other === 'dark' ? 'dunklen' : 'hellen'} Modus wechseln`;
      return {
        label: to,
        title: override ? `Zurück zur Systemeinstellung (${other === 'dark' ? 'dunkel' : 'hell'})` : to,
      };
    },
  },
  attribution: 'Datenquelle: Stadt Wien – data.wien.gv.at',
  view: { maxScale: 6, besideHud: true },
  blockingOverlays: ['water'], // a tap on the water does nothing (owner's call), like one outside the city
};
